PREFIX id: <https://id.parliament.uk/>
PREFIX : <https://id.parliament.uk/schema/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?step ?stepName ?procedure ?procedureLabel ?procedureDescription WHERE {
  ?step a :ProcedureStep;
  :name ?stepName.

  {
    ?step :procedureStepIsFromProcedureRoute ?procedureRoute.
  } UNION {
    ?step :procedureStepIsToProcedureRoute ?procedureRoute.
  }

  ?procedureRoute :procedureRouteHasProcedure ?procedure.
  ?procedure :name ?procedureLabel.
  OPTIONAL { ?procedure :procedureDescription ?procedureDescription. }
}
ORDER BY ?procedureDisplayOrder ?procedureName
LIMIT 5

step_routes.query:
PREFIX id: <https://id.parliament.uk/>
PREFIX : <https://id.parliament.uk/schema/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?route ?startDate ?endDate ?fromStep ?fromStepName ?fromStepType ?fromStepTypeName ?fromStepCommonsId ?fromStepLordsId ?fromSteplegislature ?fromSteplegislatureName ?toStep ?toStepName ?toStepType ?toStepTypeName ?toStepCommonsId ?toStepLordsId ?toSteplegislature ?toSteplegislatureName WHERE {

  ?step a :ProcedureStep;
  :name ?stepName.
  ?step :procedureStepIsFromProcedureRoute | :procedureStepIsToProcedureRoute ?route.
  OPTIONAL {?route:procedureRouteStartDate ?startDate}
  OPTIONAL {?route :procedureRouteEndDate ?endDate}
  ?route :procedureRouteIsFromProcedureStep ?fromStep.
  ?route :procedureRouteIsToProcedureStep ?toStep.
  ?fromStep :name ?fromStepName;
  :procedureStepHasProcedureStepType ?fromStepType.
  ?fromStepType :name ?fromStepTypeName.
  ?toStep :name ?toStepName;
  :procedureStepHasProcedureStepType ?toStepType.
  ?toStepType :name ?toStepTypeName.
  OPTIONAL {?fromStep :procedureStepHasHouse ?fromStepCommonsId.
    FILTER (?fromStepCommonsId IN (id:1AFu55Hs))}
  OPTIONAL {?fromStep :procedureStepHasHouse ?fromStepLordsId.
    FILTER (?fromStepLordsId IN (id:WkUWUBMx))}
  OPTIONAL {?fromStep :procedureStepInLegislature ?fromSteplegislature.
    ?fromSteplegislature :name ?fromSteplegislatureName.}
  OPTIONAL {?toStep :procedureStepHasHouse ?toStepCommonsId.
    FILTER (?toStepCommonsId IN (id:1AFu55Hs))}
  OPTIONAL {?toStep :procedureStepHasHouse ?toStepLordsId.
    FILTER (?toStepLordsId IN (id:WkUWUBMx))}
  OPTIONAL {?toStep :procedureStepInLegislature ?toSteplegislature.
    ?toSteplegislature :name ?toSteplegislatureName.}
} ORDER BY ?fromStepName
LIMIT 5

step_types.query:
PREFIX id: <https://id.parliament.uk/>
PREFIX : <https://id.parliament.uk/schema/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?stepType ?stepTypeName  WHERE {

  ?stepType a :ProcedureStepType;
  :name ?stepTypeName.

} ORDER BY ASC(UCASE(STR(?stepTypeName)))
LIMIT 5

treaty_work_packages.query:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX : <https://id.parliament.uk/schema/>
PREFIX id: <https://id.parliament.uk/>
SELECT DISTINCT ?paper ?papername ?workPackage ?businessItem ?combinedDate ?procedure ?procedure ?procedureName ?calculationStyle ?calculationStyleName (BOUND(?stepId3) AS ?hasCommitteeConcernsFlag)
(BOUND(?stepId4) AS ?hasMotionTabledFlag)  WHERE {

  ?paper a :Treaty.
  ?paper :name ?papername ;
  :workPackagedThingHasWorkPackage ?workPackage.
  OPTIONAL {   ?workPackage :workPackageHasBusinessItem ?businessItem .
    ?businessItem :businessItemHasProcedureStep ?step;
    :businessItemDate ?businessItemDate.
    FILTER (?step IN (id:isWn7s3K, id:cspzmb6w, id:ITNO9JWr, id:otscOTzB))}
  OPTIONAL {    ?workPackage :workPackageHasBusinessItem ?businessItem2 .
    ?businessItem2 :businessItemHasProcedureStep ?step2;
    :businessItemDate ?businessItemDate2.
    FILTER (?step2 IN (id:AmYrFxwO))}
  ?workPackage :workPackageHasProcedure ?procedure.
  ?procedure :name ?procedureName.
  OPTIONAL { ?workPackage :workPackageHasCalculationStyle ?calculationStyle.
    ?calculationStyle :name ?calculationStyleName. }
  OPTIONAL {
    ?workPackage :workPackageHasBusinessItem ?bi3 .
    ?bi3 :businessItemHasProcedureStep ?stepId3 .
    ?stepId3 :procedureStepHasProcedureStepCollectionMembership/
    :procedureStepCollectionMembershipHasProcedureStepCollection id:7CBVQcZF
  }

  OPTIONAL {
    ?workPackage :workPackageHasBusinessItem ?bi4 .
    ?bi4 :businessItemHasProcedureStep ?stepId4 .
    ?stepId4 :procedureStepHasProcedureStepCollectionMembership/
    :procedureStepCollectionMembershipHasProcedureStepCollection id:l3g2umNB
  }
  BIND(COALESCE(?businessItemDate, ?businessItemDate2) AS ?combinedDate)
} ORDER BY DESC(?combinedDate) ?papername
LIMIT 5

work_package.query:
PREFIX : <https://id.parliament.uk/schema/>
PREFIX id: <https://id.parliament.uk/>

SELECT * WHERE {
  ?paper a :WorkPackagedThing .
  ?paper :name ?paperName ;
  :workPackagedThingHasWorkPackage ?workPackage.

  OPTIONAL {?paper :workPackagedThingHasWorkPackagedThingWebLink ?workPackagedThingWebLink.}

  OPTIONAL {?paper :laidThingHasLaying ?laying.
    ?laying :layingDate ?laidDate;
    :businessItemHasProcedureStep ?step.

    FILTER (?step IN (id:isWn7s3K, id:cspzmb6w))}

  ?workPackage :workPackageHasProcedure ?procedure.
  ?procedure :name ?procedureName.

  OPTIONAL{ ?workPackage :workPackageHasCalculationStyle ?calculationStyle.
    ?calculationStyle :name ?calculationStyleName. }

}
LIMIT 5

work_package_business_items.query:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX : <https://id.parliament.uk/schema/>
PREFIX id: <https://id.parliament.uk/>
SELECT * WHERE {

  ?paper a :WorkPackagedThing .
  ?paper :name ?papername ;
  :workPackagedThingHasWorkPackage ?workPackage.
  ?workPackage :workPackageHasBusinessItem ?businessItem.
  ?workPackage :workPackageHasProcedure ?procedure.
  OPTIONAL {?businessItem :businessItemDate ?businessItemDate}
  OPTIONAL {?businessItem :businessItemHasBusinessItemWebLink ?businessItemLink}
  ?businessItem :businessItemHasProcedureStep ?businessItemProcedureStep.
  ?businessItemProcedureStep :name ?businessItemProcedureStepName.
  OPTIONAL {  ?businessItemProcedureStep :procedureStepHasStepDisplayDepthInProcedure ?stepDepth.
    ?procedure :procedureHasStepDisplayDepthInProcedure ?stepDepth.
    ?stepDepth :stepDisplayDepthInProcedureHasDepth ?depthValue.}
  OPTIONAL {?businessItemProcedureStep :procedureStepInLegislature ?legislature.
    ?legislature :name ?legislatureName.}
  OPTIONAL {?businessItemProcedureStep :procedureStepHasHouse ?commonsId.
    FILTER (?commonsId IN (id:1AFu55Hs))}
  OPTIONAL {?businessItemProcedureStep :procedureStepHasHouse ?lordsId.
    FILTER (?lordsId IN (id:WkUWUBMx))} }  ORDER BY ?businessItemDate ?depthValue ?businessItem
LIMIT 5

work_packageable_thing.query:
PREFIX id: <https://id.parliament.uk/>
PREFIX : <https://id.parliament.uk/schema/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?workPackage ?workPackagedThing ?workPackagedThingName ?madeAvailableDate ?procedure ?procedureName ?webLink ?sIprefix ?sINumber ?sIYear ?commandPrefix ?commandPaperNumber  WHERE {
  ?workPackagedThing a :WorkPackagedThing;
  :name ?workPackagedThingName;
  :workPackagedThingHasWorkPackage ?workPackage.
  ?workPackage :workPackageHasProcedure ?procedure.
  ?procedure :name ?procedureName.
  OPTIONAL {?workPackagedThing :workPackagedThingHasWorkPackagedThingWebLink ?webLink.}
  OPTIONAL {?workPackagedThing :statutoryInstrumentPaperPrefix ?sIprefix}
  OPTIONAL {?workPackagedThing :statutoryInstrumentPaperNumber ?sINumber}
  OPTIONAL {?workPackagedThing :statutoryInstrumentPaperYear ?sIYear}
  OPTIONAL {?workPackagedThing :treatyCommandPaperNumber ?commandPaperNumber}
  OPTIONAL {?workPackagedThing :treatyCommandPaperPrefix ?commandPrefix}
  OPTIONAL {?workPackage :workPackageHasBusinessItem ?businessItem .
    ?businessItem :businessItemHasProcedureStep ?step;
    :businessItemDate ?madeAvailableDate.
    FILTER (?step IN (id:isWn7s3K, id:cspzmb6w, id:ITNO9JWr, id:otscOTzB))}
LIMIT 5
